      "ar": "قَالَ أَرَءَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ وَمَا أَنسَىٰنِيهُ إِلَّا الشَّيْطَٰنُ أَنْ أَذْكُرَهُ وَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ عَجَبًا",
      "translit": "Qāla araʾayta idh awaynā ilā ṣ-ṣakhrati faʾinnī nasītu l-ḥūta wamā ansānīhu illā sh-shayṭānu an adhkurahū wattakhadha sabīlahū fī l-baḥri ʿajabā",
