      "numero": 88,
      "ar": "وَأَمَّا مَنْ ءَامَنَ وَعَمِلَ صَٰلِحًا فَلَهُ جَزَاءً الْحُسْنَىٰ وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا",
      "translit": "Waʾammā man āmana waʿamila ṣāliḥan falahū jazāʾan l-ḥusnā wasanaqūlu lahū min amrinā yusrā",
