    "declic_frequence": "ṣabara (patienter, endurer, racine ص-ب-ر) est le cœur du récit de Moïse et al-Khiḍr : innaka lan tastaṭīʿa maʿiya ṣabran — « tu ne saurais être patient avec moi » (v.67). Le ṣabr n'est pas seulement endurer l'épreuve, mais accepter de ne pas comprendre : Moïse, prophète et détenteur de la Loi, ne supporte pas les actes d'al-Khiḍr car leur sagesse cachée lui échappe. Le récit enseigne que la patience suprême consiste à faire confiance au dessein divin quand sa logique nous dépasse — le savoir humain, si haut soit-il, reste partiel."
